-- Appended to the rolled-back stage3 fixture transaction; no Cloud fixture writes.
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
SET LOCAL session_replication_role=replica;
INSERT INTO public.role_permission(role_code,permission_code)
 SELECT 'ADMIN',unnest(ARRAY['service.read','service.write','service_category.read','staff_level.read','pet_species.read','service_supported_species.read','service_care_action.read','care_action.read','audit_log.read','staff.read','service_supported_species.write','service_care_action.write','care_action.write','audit_log.write']) ON CONFLICT DO NOTHING;
INSERT INTO public.service_category(id,category_code,category_name) VALUES('51000000-0000-0000-0000-000000000001','grooming_spa','Isolated service category');
INSERT INTO public.pet_species(id,species_name) VALUES('52000000-0000-0000-0000-000000000001','Isolated species');
INSERT INTO public.service(id,service_code,service_name,estimated_duration,category_id) VALUES
 ('53000000-0000-0000-0000-000000000001','ISOLATED-SERVICE','Isolated service',30,'51000000-0000-0000-0000-000000000001'),
 ('53000000-0000-0000-0000-000000000002','OTHER-SERVICE','Other service',30,'51000000-0000-0000-0000-000000000001');
SET LOCAL session_replication_role=origin;
SELECT set_config('service.details','{"service_code":"ISOLATED-SERVICE","service_name":"Isolated service","duration_minutes":30,"category_code":"grooming_spa","status":"active","species_ids":["52000000-0000-0000-0000-000000000001"],"steps":[]}',true);
SET LOCAL ROLE authenticated;
SELECT set_config('service.session',public.prepare_service_media_upload(gen_random_uuid(),'53000000-0000-0000-0000-000000000001',null,100,'image/png','service.png')->>'session_id',true);
SELECT set_config('service.lease',public.claim_media_upload(current_setting('service.session')::uuid)->>'lease',true);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('service.asset',public.finish_media_upload(current_setting('service.session')::uuid,current_setting('service.lease')::uuid,'10000000-0000-0000-0000-000000000001',repeat('9',64),2,2)::text,true);
RESET ROLE;
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('service.asset')::uuid) IS NULL,'service draft private');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.expect_error($q$INSERT INTO public.product_media(product_id,media_asset_id) VALUES('30000000-0000-0000-0000-000000000001',current_setting('service.asset')::uuid)$q$,'42501');
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect_error($q$SELECT pawpal_private.sync_service_media('53000000-0000-0000-0000-000000000002',jsonb_build_array(jsonb_build_object('asset_id',current_setting('service.asset'))))$q$,'42501');
SELECT set_config('service.details',(current_setting('service.details')::jsonb||jsonb_build_object('media_sources',jsonb_build_array(jsonb_build_object('asset_id',current_setting('service.asset')))))::text,true);
SELECT public.save_admin_service_catalog('53000000-0000-0000-0000-000000000001',(SELECT updated_at FROM public.service WHERE id='53000000-0000-0000-0000-000000000001'),current_setting('service.details')::jsonb,null);
RESET ROLE;
SELECT set_config('service.ref',(SELECT id::text FROM public.service_image WHERE media_asset_id=current_setting('service.asset')::uuid),true);
SET LOCAL ROLE authenticated;
SELECT public.save_admin_service_catalog('53000000-0000-0000-0000-000000000001',(SELECT updated_at FROM public.service WHERE id='53000000-0000-0000-0000-000000000001'),current_setting('service.details')::jsonb,null);
RESET ROLE;
SELECT pg_temp.assert((SELECT id::text=current_setting('service.ref') FROM public.service_image WHERE media_asset_id=current_setting('service.asset')::uuid),'service reference retained');
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT pg_temp.assert((public.resolve_media_asset(current_setting('service.asset')::uuid)->>'public')::boolean,'active service image public');
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.public_service_directory()) x WHERE x->>'id'='53000000-0000-0000-0000-000000000001' AND x->'images'->>0='/api/media?action=read&id='||current_setting('service.asset')),'public directory resolves service asset');
RESET ROLE;
UPDATE public.service SET status='inactive' WHERE id='53000000-0000-0000-0000-000000000001';
SET LOCAL ROLE anon;
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('service.asset')::uuid) IS NULL,'inactive service denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.expect_error($q$SELECT public.prepare_service_media_upload(gen_random_uuid(),'53000000-0000-0000-0000-000000000001',null,100,'image/png','bad.png')$q$,'42501');
SELECT pg_temp.expect_error($q$SELECT pawpal_private.sync_service_media('53000000-0000-0000-0000-000000000001','[]')$q$,'42501');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT pawpal_private.sync_service_media('53000000-0000-0000-0000-000000000001','[]');
RESET ROLE;
SELECT pg_temp.assert((SELECT state='pending_delete' FROM public.media_upload_session WHERE id=current_setting('service.session')::uuid),'service detach retains pending cleanup');
SET LOCAL ROLE authenticated;
SELECT set_config('service.draft_session',public.prepare_service_media_upload(gen_random_uuid(),null,'53000000-0000-0000-0000-000000000003',100,'image/png','draft.png')->>'session_id',true);
SELECT set_config('service.draft_lease',public.claim_media_upload(current_setting('service.draft_session')::uuid)->>'lease',true);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('service.draft_asset',public.finish_media_upload(current_setting('service.draft_session')::uuid,current_setting('service.draft_lease')::uuid,'10000000-0000-0000-0000-000000000001',repeat('8',64),2,2)::text,true);
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT public.save_admin_service_catalog('53000000-0000-0000-0000-000000000003',null,current_setting('service.details')::jsonb||jsonb_build_object('service_code','ISOLATED-NEW-SERVICE','media_sources',jsonb_build_array(jsonb_build_object('asset_id',current_setting('service.draft_asset')))),null);
RESET ROLE;
SELECT pg_temp.assert((SELECT service_id='53000000-0000-0000-0000-000000000003'::uuid AND state='attached' FROM public.media_upload_session WHERE id=current_setting('service.draft_session')::uuid),'draft service adopted');
